"use client";

import React from 'react';
import Link from 'next/link';
import { Heart, ArrowLeft, ShoppingBag, Trash2 } from 'lucide-react';
import { Product } from '../types';
import { useWishlist } from '../context/WishlistContext';
import { ProductCard } from '../components/shop/ProductCard';

interface WishlistPageProps {
  products?: Product[];
  onSelectProduct?: (product: Product) => void;
  onExploreProducts?: () => void;
}

export const WishlistPage: React.FC<WishlistPageProps> = ({
  products = [],
  onSelectProduct,
  onExploreProducts,
}) => {
  const { wishlist = [], wishlistIds = [], clearWishlist } = useWishlist() as any;

  // Izračunavanje ID-jeva iz konteksta
  const rawIds = wishlistIds.length > 0 ? wishlistIds : wishlist;
  const normalizedWishlistIds = (rawIds || []).map((item: any) => {
    if (typeof item === 'object' && item !== null) {
      return String(item.id || item._id || '').trim();
    }
    return String(item || '').trim();
  }).filter(Boolean);

  const wishlistProducts = (products || []).filter((p) => {
    if (!p) return false;
    const prodId = String(p.id || (p as any)._id || '').trim();
    return normalizedWishlistIds.includes(prodId);
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 sm:py-14 space-y-8 animate-fadeIn font-['Inter']">
      
      {/* Zaglavlje */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b-2 border-neutral-200">
        <div>
          <Link
            href="/shop"
            className="inline-flex items-center gap-1.5 text-xs font-['Poppins'] font-bold uppercase tracking-wider text-neutral-500 hover:text-black mb-2 transition-colors cursor-pointer"
          >
            <ArrowLeft className="w-3.5 h-3.5" />
            <span>Nazad na ponudu</span>
          </Link>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-[#0A0A0A] text-[#F7E97F] flex items-center justify-center shrink-0">
              <Heart className="w-5 h-5 fill-[#F7E97F]" />
            </div>
            <div>
              <h1 className="font-['Poppins'] text-2xl sm:text-4xl font-black uppercase tracking-tight text-[#0A0A0A]">
                Moja lista želja
              </h1>
              <p className="text-xs text-neutral-500">
                Vaši sačuvani komadi za brzu kupovinu ({wishlistProducts.length})
              </p>
            </div>
          </div>
        </div>

        {wishlistProducts.length > 0 && (
          <button
            type="button"
            onClick={() => {
              if (confirm('Jeste li sigurni da želite ukloniti sve artikle iz liste želja?')) {
                clearWishlist();
              }
            }}
            className="px-4 py-2 border border-neutral-300 hover:border-black text-xs font-['Poppins'] font-bold uppercase tracking-wider text-neutral-600 hover:text-black flex items-center gap-1.5 transition-colors cursor-pointer w-fit"
          >
            <Trash2 className="w-3.5 h-3.5" />
            <span>Isprazni listu</span>
          </button>
        )}
      </div>

      {/* Sadržaj ili Prazno stanje */}
      {wishlistProducts.length === 0 ? (
        <div className="bg-white border-2 border-neutral-200 p-8 sm:p-12 text-center space-y-4 max-w-xl mx-auto shadow-sm">
          <div className="w-16 h-16 bg-[#FAF9F5] text-[#0A0A0A] rounded-full flex items-center justify-center mx-auto border-2 border-neutral-300">
            <Heart className="w-8 h-8 text-neutral-400" />
          </div>
          <h2 className="font-['Poppins'] text-lg font-black uppercase tracking-wider text-black">
            Vaša lista želja je prazna
          </h2>
          <p className="text-xs text-neutral-600">
            Kliknite na ikonicu srca na bilo kojem artiklu u trgovini kako biste ga spremili ovdje.
          </p>
          <div className="pt-2">
            <Link
              href="/shop"
              className="px-6 py-3.5 bg-[#0A0A0A] text-white hover:bg-[#F7E97F] hover:text-[#0A0A0A] font-['Poppins'] text-xs font-black uppercase tracking-[0.2em] transition-all inline-flex items-center gap-2 border-2 border-[#0A0A0A] cursor-pointer"
            >
              <ShoppingBag className="w-4 h-4" />
              <span>Istraži ponudu artikala</span>
            </Link>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 sm:gap-6">
          {wishlistProducts.map((prod) => (
            <ProductCard 
              key={prod.id} 
              product={prod} 
              onSelect={onSelectProduct || ((p) => window.location.href = `/proizvod/${p.id}`)} 
            />
          ))}
        </div>
      )}
    </div>
  );
};